const e={ocnal:{baipishu:"Weißbuch",home1:"Entdecke die Welt der digitalen Währungen",home2:"Jetzt einzahlen",home3:"Name",home4:"Preis",home5:"24h Änderung",home6:"Handeln",home7:"Erste Schritte",home8:"Konto erstellen",home9:"Registrieren Sie ein Konto, um mehr Vorteile und Dienstleistungen zu genießen",home10:"Registrieren",home11:"Guthaben einzahlen",home12:"Laden Sie Ihr Konto auf und beginnen Sie mit dem Investieren in Kryptowährungen",home13:"Krypto einzahlen",home14:"Mit dem Handel beginnen",home15:"Verkaufen, kaufen oder Trades kopieren – entdecken Sie mehr Möglichkeiten",home16:"Den Markt erkunden",home17:"Der Kryptowährungsmarkt boomt und umfasst digitale Währungen, Blockchain-Technologie und mehr. Die Aussichten sind vielversprechend, aber Investitionen erfordern Vorsicht.",home18:"Spot",home19:"Echtzeithandelsmarkt mit schnellen Preisänderungen.",home20:"Perpetual Contract",home21:"Der Handel mit Verträgen bietet Hebelwirkung, um hohe Renditen zu erzielen.",home22:"Optionen",home23:"Optionshandel bietet flexible Absicherungsstrategien, um Risiken zu kontrollieren und Erträge zu erzielen.",home24:"Finanzen",home25:"Planen Sie mit Vertrauen. Investieren Sie klug. Sorgen Sie weniger.",home26:"Die höchste jährliche Rendite in der Geschichte",home27:"Flexibel",home28:"Festzins",home29:"Jetzt kaufen",home30:"Jeder kann digitale Währungen nutzen",home31:"Von der ersten Erfahrung im Kryptohandel bis zum ersten Finanzproduktkauf hilft Ihnen die Plattform, mühelos Coins zu verdienen",home32:"Über Kryptowährungen lernen",home33:"Erfahren Sie alles über Kryptowährungen und starten Sie Ihre Investition",home34:"Häufig gestellte Fragen",home35:"Bereit, Ihre Krypto-Reise zu beginnen?",home36:"Was ist eine Kryptowährungsbörse?",home37:"Kryptowährungsbörsen sind digitale Marktplätze, auf denen Benutzer Kryptowährungen wie Bitcoin, Ethereum und Tether kaufen und verkaufen können. Binance ist die größte Krypto-Börse nach Handelsvolumen.",home38:"Welche Produkte bietet die Plattform an?",home39:"Als führende globale Krypto-Handelsplattform bedient sie über 150 Millionen registrierte Nutzer in mehr als 180 Ländern. Mit niedrigen Gebühren bietet sie über 350 handelbare Kryptowährungen und ist die bevorzugte Wahl für Bitcoin-, Altcoin- und digitale Asset-Trades.<br><br>Auf der Plattform können Benutzer:<br><br>1. Hunderte digitaler Währungen und Paare handeln.<br><br>2. Kryptowährungen über Spot-Handel kaufen und verkaufen.<br><br>3. Zinsen durch Krypto-Vermögensverwaltung verdienen.",home40:"Wie man auf der Plattform Kryptowährungen handelt",home41:"Auf der Plattform können Sie Hunderte von Kryptowährungen auf dem Spot-, Futures- und Optionsmarkt handeln. Registrieren Sie ein Konto, verifizieren Sie Ihre Identität und zahlen Sie Kryptowährungen ein, um mit dem Handel zu beginnen.",home42:"Ist diese Plattform sicher?",home43:"Diese Plattform ist bestrebt, eine sichere und vertrauenswürdige Handelsumgebung zu bieten. Wir verfügen über modernste Sicherheitstechnologien und ein engagiertes Team, das ständig daran arbeitet, Ihre Vermögenswerte zu schützen. Alle Benutzervermögen sind im Verhältnis 1:1 vollständig abgesichert.",home44:"Wie kann ich mein Passwort zurücksetzen?",home45:"Klicken Sie auf der Anmeldeseite auf „Passwort vergessen“, um Ihr Login-Passwort zurückzusetzen.",home46:"Warum ist eine Identitätsprüfung erforderlich?",home47:"Zum Schutz Ihrer Gelder und zur Verhinderung von Geldwäsche müssen wir sicherstellen, dass Ihr Empfangskonto mit Ihren Identitätsinformationen übereinstimmt.",home48:"Märkte",home49:"Der globale Kryptowährungshandelsmarkt unterstützt Mehrwährungstransaktionen und bietet sowohl Sicherheit als auch Effizienz.",home50:"Mein Konto",home51:"Einzahlen",home52:"Abheben",home53:"Konvertieren",home54:"Beliebt",home55:"Investieren Sie in neu ausgegebene Token und nutzen Sie das hohe Renditepotenzial",home56:"Nachrichten",home57:"Warum uns wählen?",home58:"Von Millionen vertraut",home59:"Anzahl der Benutzer",home60:"Partnerunternehmen",home61:"Minimale Transaktionsgebühren",home62:"Partner",home63:"24h Handelsvolumen"}};export{e as default};
